var ITEMS=[["Rolls-Royce: overview","Rolls-Royce: British ultra-luxury maker founded 1904; BMW-owned.."], ["name","Rolls-Royce"], ["origin","British ultra-luxury maker founded 1904; BMW-owned."]];
function ask(n){var out=[],seen={};n=Math.min(n,ITEMS.length);for(var k=0;k<n;k++){var it=ITEMS[(Math.random()*ITEMS.length)|0];out.push("Q"+(k+1)+": "+it[0]+"\nA"+(k+1)+": "+it[1]);}return out.join("\n\n");}
